      "reason": "동일 인수 범위 OOS [0, 0, 0, 0]: 각 후보 최소 4개 및 학습 8개 조건 미충족. 비교 가능한 동일 검증 분기에서 모든 기준모형보다 낮은 MAE가 확인되지 않았습니다. 현재 분기 산업 자료가 미완결입니다. 시차 입력의 완결성과 현재 분기 원관측을 별도로 표시합니다. 최근/다음 분기 범위 변경: AEG Power Solutions CAD/IFRS 매출과 USD 수입액은 환산하지 않습니다. AEG는 6월29일 인수되어 6월27일 종료 Q2에 미포함이며 다음 분기 말일도 미확정입니다. 산업 통계는 회사 출하·점유율·귀속 매출이 아니며, 수치 예측 공개를 승인하지 않았습니다.",
